command:
/** Open the Gullet for the selected token's Assimilator, or your own character's. */
const api = game.modules.get("isaacs-hb-pf2e").api;
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) ui.notifications.warn("Select an Assimilator's token, or assign yourself a character.");
else api.assimilator.openGullet(actor);
